  -- 878 Sound
  (878,'govt_technical','snd-concept','concept',1,'ध्वनि — SSC JE / RRB JE',$j${"note":"JE में श्रव्य परास (20 Hz – 20 kHz) और प्रतिध्वनि की न्यूनतम दूरी अक्सर पूछी जाती है।","text":"ध्वनि अनुदैर्ध्य तरंग है और ठोस, द्रव, गैस में चलती है। हवा में चाल लगभग 340 m/s। 20 Hz से 20 kHz की ध्वनि मनुष्य सुन सकता है। 20 Hz से कम अवश्रव्य और 20 kHz से ऊपर पराश्रव्य कहलाती है।"}$j$),
  (878,'govt_technical','snd-formula','formula',2,'प्रतिध्वनि का सूत्र',$j${"formula":"d = v × t / 2","explanation":"d = स्रोत से परावर्तक सतह की दूरी (m), v = ध्वनि की चाल (m/s), t = प्रतिध्वनि लौटने का समय (s) · प्रतिध्वनि सुनने के लिए d ≥ 17 m (हवा में)"}$j$),
  (878,'govt_technical','snd-example','example',3,'Numerical (JE style)',$j${"question":"हवा में ध्वनि की चाल 340 m/s है। प्रतिध्वनि 0.2 s में लौटती है। दीवार कितनी दूर है?","solution":"d = 340 × 0.2 / 2 = 34 m","answer":"34 m"}$j$),
  (878,'govt_technical','snd-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"मनुष्य के कान के लिए श्रव्य आवृत्ति परास क्या है?","options":["20 Hz – 20 kHz","2 Hz – 2 kHz","200 Hz – 2 MHz","0 – 20 Hz"],"answer":0,"explanation":"मनुष्य 20 Hz से 20 kHz की ध्वनि सुन सकता है।"},{"q":"प्रतिध्वनि सुनने के लिए परावर्तक सतह की न्यूनतम दूरी लगभग कितनी होनी चाहिए?","options":["17 m","1.7 m","170 m","1.7 km"],"answer":0,"explanation":"हवा में प्रतिध्वनि अलग सुनने के लिए लगभग 17 m दूरी चाहिए।"}]}$j$),
  (878,'govt_basic','snd-concept','concept',1,'ध्वनि',$j${"note":"परीक्षा में ध्वनि की चाल और आवृत्ति का मात्रक पूछे जाते हैं।","text":"ध्वनि एक प्रकार की ऊर्जा है जो कंपन से पैदा होती है। ध्वनि को चलने के लिए माध्यम (ठोस, द्रव या गैस) चाहिए, खाली जगह में नहीं चलती। हवा में चाल लगभग 340 m/s है।"}$j$),
  (878,'govt_basic','snd-formula','formula',2,'ध्वनि की चाल',$j${"formula":"v = f × λ","explanation":"v = ध्वनि की चाल (m/s), f = आवृत्ति (Hz), λ = तरंगदैर्घ्य (m)"}$j$),
  (878,'govt_basic','snd-example','example',3,'उदाहरण',$j${"question":"ध्वनि की आवृत्ति 340 Hz और तरंगदैर्घ्य 1 m है। चाल कितनी है?","solution":"v = 340 × 1 = 340 m/s","answer":"340 m/s"}$j$),
  (878,'govt_basic','snd-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"ध्वनि को चलने के लिए क्या चाहिए?","options":["माध्यम","निर्वात","प्रकाश","चुंबक"],"answer":0,"explanation":"ध्वनि को चलने के लिए ठोस, द्रव या गैस जैसा माध्यम चाहिए।"},{"q":"20 kHz से ऊपर की ध्वनि क्या कहलाती है?","options":["पराश्रव्य","अवश्रव्य","श्रव्य","प्रतिध्वनि"],"answer":0,"explanation":"20 kHz से ऊपर की ध्वनि पराश्रव्य (ultrasonic) कहलाती है।"}]}$j$),
  (878,null,'snd-diagram','svg',5,'ध्वनि तरंग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='50' cy='60' r='10' fill='#14b8a6'/><path d='M 80 40 A 30 30 0 0 1 80 80' fill='none' stroke='#14b8a6' stroke-width='3'/><path d='M 110 25 A 50 50 0 0 1 110 95' fill='none' stroke='#14b8a6' stroke-width='3'/><path d='M 140 10 A 70 70 0 0 1 140 110' fill='none' stroke='#14b8a6' stroke-width='3'/><text x='150' y='118' text-anchor='middle' fill='#64748b' font-size='11'>ध्वनि तरंगें फैलती हैं</text></svg>","caption":"ध्वनि स्रोत से तरंगों के रूप में चारों ओर फैलती है"}$j$),
  -- 879 Light & Optics
  (879,'govt_technical','lgt-concept','concept',1,'प्रकाशिकी — SSC JE / RRB JE',$j${"note":"JE में लेंस का सूत्र, क्षमता (D) और निकट/दूर दृष्टि अक्सर पूछे जाते हैं।","text":"प्रकाश का निर्वात में वेग 3×10⁸ m/s है। उत्तल लेंस (convex) अभिसारी और अवतल लेंस (concave) अपसारी होता है। लेंस की क्षमता P = 1/f (मीटर में f), मात्रक डायॉप्टर (D)।"}$j$),
  (879,'govt_technical','lgt-formula','formula',2,'लेंस का सूत्र',$j${"formula":"1/f = 1/v − 1/u","explanation":"f = फोकस दूरी, v = प्रतिबिंब की दूरी, u = वस्तु की दूरी (चिह्न-परिपाटी के अनुसार) · क्षमता P = 1/f"}$j$),
  (879,'govt_technical','lgt-example','example',3,'Numerical (JE style)',$j${"question":"फोकस दूरी 0.2 m वाले लेंस की क्षमता कितनी है?","solution":"P = 1/f = 1/0.2 = 5 D","answer":"5 D"}$j$),
  (879,'govt_technical','lgt-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"दूरदृष्टि (hypermetropia) दोष के लिए कौन सा लेंस उपयोग होता है?","options":["उत्तल लेंस","अवतल लेंस","बेलनाकार लेंस","समतल काँच"],"answer":0,"explanation":"दूरदृष्टि में पास की वस्तु साफ नहीं दिखती, इसके लिए उत्तल लेंस उपयोग होता है।"},{"q":"प्रकाश का निर्वात में वेग लगभग कितना है?","options":["3×10⁸ m/s","3×10⁶ m/s","3×10⁴ m/s","3×10¹⁰ m/s"],"answer":0,"explanation":"निर्वात में प्रकाश की चाल लगभग 3×10⁸ m/s है।"}]}$j$),
  (879,'govt_basic','lgt-concept','concept',1,'प्रकाश और दर्पण',$j${"note":"परीक्षा में अवतल दर्पण और उत्तल लेंस के उपयोग पूछे जाते हैं।","text":"प्रकाश सीधी रेखा में चलता है। समतल दर्पण में प्रतिबिंब सीधा और आभासी होता है। अवतल दर्पण से प्रतिबिंब बड़ा हो सकता है, जबकि उत्तल दर्पण से प्रतिबिंब हमेशा छोटा और सीधा बनता है।"}$j$),
  (879,'govt_basic','lgt-formula','formula',2,'दर्पण का सूत्र',$j${"formula":"1/f = 1/v + 1/u","explanation":"f = फोकस दूरी, u = वस्तु की दूरी, v = प्रतिबिंब की दूरी · गोलीय दर्पण में f = R/2"}$j$),
  (879,'govt_basic','lgt-example','example',3,'उदाहरण',$j${"question":"अवतल दर्पण की वक्रता त्रिज्या 40 cm है। फोकस दूरी कितनी है?","solution":"f = R / 2 = 40 / 2 = 20 cm","answer":"20 cm"}$j$),
  (879,'govt_basic','lgt-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"प्रकाश की चाल निर्वात में लगभग कितनी है?","options":["3×10⁸ m/s","3×10⁵ m/s","3×10² m/s","3×10¹¹ m/s"],"answer":0,"explanation":"निर्वात में प्रकाश की चाल 3×10⁸ m/s है।"},{"q":"समतल दर्पण में प्रतिबिंब कैसा बनता है?","options":["सीधा और आभासी","उल्टा और वास्तविक","बड़ा और वास्तविक","छोटा और उल्टा"],"answer":0,"explanation":"समतल दर्पण में प्रतिबिंब सीधा, आभासी और वस्तु के बराबर आकार का होता है।"}]}$j$),
  (879,null,'lgt-diagram','svg',5,'प्रकाश का परावर्तन',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><line x1='20' y1='100' x2='280' y2='100' stroke='#64748b' stroke-width='3'/><line x1='60' y1='20' x2='150' y2='100' stroke='#f59e0b' stroke-width='3'/><line x1='150' y1='100' x2='240' y2='20' stroke='#14b8a6' stroke-width='3'/><line x1='150' y1='100' x2='150' y2='60' stroke='#64748b' stroke-dasharray='4,3'/><text x='150' y='118' text-anchor='middle' fill='#64748b' font-size='11'>आपतन कोण = परावर्तन कोण</text></svg>","caption":"परावर्तन में आपतन कोण और परावर्तन कोण बराबर होते हैं"}$j$),
  -- 880 Electricity
  (880,'govt_technical','elec-concept','concept',1,'विद्युत — SSC JE / RRB JE',$j${"note":"JE में ओम का नियम, श्रेणी/समानांतर संयोजन और kWh अक्सर पूछे जाते हैं।","text":"ओम का नियम: V = IR (स्थिर ताप पर)। विद्युत शक्ति P = VI = I²R = V²/R। ऊर्जा का व्यावसायिक मात्रक kWh है। श्रेणी में कुल R = R₁+R₂; समानांतर में 1/R = 1/R₁+1/R₂।"}$j$),
  (880,'govt_technical','elec-formula','formula',2,'शक्ति का सूत्र',$j${"formula":"P = V²/R","explanation":"P = शक्ति (W), V = वोल्टेज (V), R = प्रतिरोध (Ω) · ऊर्जा (kWh) = किलोवाट × घंटे"}$j$),
  (880,'govt_technical','elec-example','example',3,'Numerical (JE style)',$j${"question":"2000 W का हीटर 5 घंटे चलता है। कुल ऊर्जा कितनी खर्च होगी?","solution":"ऊर्जा = 2 kW × 5 h = 10 kWh","answer":"10 kWh"}$j$),
  (880,'govt_technical','elec-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"ओम के नियम के अनुसार V, I और R का संबंध क्या है?","options":["V = IR","V = I/R","V = R/I","V = I + R"],"answer":0,"explanation":"ओम के नियम के अनुसार V = IR।"},{"q":"समानांतर संयोजन में दो 6 Ω प्रतिरोधों का कुल प्रतिरोध कितना है?","options":["3 Ω","6 Ω","12 Ω","36 Ω"],"answer":0,"explanation":"1/R = 1/6 + 1/6 = 1/3, इसलिए R = 3 Ω।"}]}$j$),
  (880,'govt_basic','elec-concept','concept',1,'विद्युत धारा',$j${"note":"परीक्षा में धारा का मात्रक (ऐम्पियर) और ओम का नियम पूछे जाते हैं।","text":"विद्युत धारा आवेश के प्रवाह की दर है, मात्रक ऐम्पियर (A)। प्रतिरोध का मात्रक ओम (Ω) है। बल्ब, पंखा, हीटर घरेलू उपकरण हैं।"}$j$),
  (880,'govt_basic','elec-formula','formula',2,'ओम का नियम',$j${"formula":"V = I × R","explanation":"V = वोल्टेज (V), I = धारा (A), R = प्रतिरोध (Ω)"}$j$),
  (880,'govt_basic','elec-example','example',3,'उदाहरण',$j${"question":"12 V के सेल से 4 Ω प्रतिरोध जुड़ा है। धारा कितनी है?","solution":"I = V / R = 12 / 4 = 3 A","answer":"3 A"}$j$),
  (880,'govt_basic','elec-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"विद्युत धारा का SI मात्रक क्या है?","options":["ऐम्पियर","वोल्ट","ओम","वाट"],"answer":0,"explanation":"विद्युत धारा का SI मात्रक ऐम्पियर (A) है।"},{"q":"प्रतिरोध का SI मात्रक क्या है?","options":["ओम","जूल","न्यूटन","हर्ट्ज़"],"answer":0,"explanation":"प्रतिरोध का मात्रक ओम (Ω) है।"}]}$j$),
  (880,null,'elec-diagram','svg',5,'सरल विद्युत परिपथ',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='40' y='30' width='220' height='60' fill='none' stroke='#64748b' stroke-width='3'/><rect x='20' y='50' width='16' height='20' fill='#f59e0b'/><rect x='130' y='25' width='40' height='14' fill='#60a5fa'/><text x='150' y='112' text-anchor='middle' fill='#64748b' font-size='11'>सेल, प्रतिरोध और तार</text></svg>","caption":"सरल परिपथ में सेल से धारा प्रतिरोध के रास्ते बहती है"}$j$),
  -- 881 Magnetic Effects of Current
  (881,'govt_technical','mag-concept','concept',1,'चुंबकीय प्रभाव — SSC JE / RRB JE',$j${"note":"JE में फ्लेमिंग का बायाँ हाथ नियम (मोटर) और दायाँ हाथ नियम (जनरेटर) अक्सर पूछे जाते हैं।","text":"धारा वाले तार के चारों ओर चुंबकीय क्षेत्र बनता है। चुंबकीय बल F = BIL। फ्लेमिंग का बायाँ हाथ नियम मोटर पर, दायाँ हाथ नियम जनरेटर पर लागू होता है।"}$j$),
  (881,'govt_technical','mag-formula','formula',2,'चुंबकीय बल',$j${"formula":"F = B × I × L","explanation":"F = बल (N), B = चुंबकीय क्षेत्र (T), I = धारा (A), L = तार की लंबाई (m) · जब तार क्षेत्र के लंबवत हो"}$j$),
  (881,'govt_technical','mag-example','example',3,'Numerical (JE style)',$j${"question":"0.5 T क्षेत्र में 2 A धारा वाले 0.3 m तार पर बल कितना है? (तार क्षेत्र के लंबवत है)","solution":"F = 0.5 × 2 × 0.3 = 0.3 N","answer":"0.3 N"}$j$),
  (881,'govt_technical','mag-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"विद्युत मोटर किस सिद्धांत पर काम करती है?","options":["धारा वाले तार पर चुंबकीय बल","विद्युत चुंबकीय प्रेरण","ऊष्मीय प्रभाव","रासायनिक प्रभाव"],"answer":0,"explanation":"मोटर में चुंबकीय क्षेत्र में रखे धारा वाले कुंडली पर बल लगता है।"},{"q":"ट्रांसफॉर्मर किस धारा पर काम करता है?","options":["केवल प्रत्यावर्ती (AC)","केवल दिष्ट (DC)","दोनों पर","किसी पर नहीं"],"answer":0,"explanation":"ट्रांसफॉर्मर में बदलते चुंबकीय क्षेत्र के लिए AC चाहिए।"}]}$j$),
  (881,'govt_basic','mag-concept','concept',1,'चुंबकीय प्रभाव',$j${"note":"परीक्षा में चुंबक और विद्युत धारा के संबंध के उदाहरण पूछे जाते हैं।","text":"विद्युत धारा से चुंबकत्व पैदा होता है। इसी सिद्धांत पर विद्युत चुंबक, बिजली की घंटी और मोटर काम करते हैं। चुंबकीय क्षेत्र की दिशा दायें हाथ के अंगूठे नियम से निकाली जाती है।"}$j$),
  (881,'govt_basic','mag-formula','formula',2,'चुंबकीय क्षेत्र का नियम',$j${"formula":"दायें हाथ का अंगूठा नियम","explanation":"अंगूठा धारा की दिशा में, मुड़ी उँगलियाँ चुंबकीय क्षेत्र की दिशा में"}$j$),
  (881,'govt_basic','mag-example','example',3,'उदाहरण',$j${"question":"बिजली की घंटी किस प्रभाव पर काम करती है?","solution":"विद्युत चुंबक के चुंबकीय प्रभाव से हथौड़ी लोहे की प्लेट से टकराती है","answer":"चुंबकीय प्रभाव"}$j$),
  (881,'govt_basic','mag-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"धारा वाले तार के चारों ओर क्या बनता है?","options":["चुंबकीय क्षेत्र","गुरुत्वीय क्षेत्र","ध्वनि क्षेत्र","प्रकाश"],"answer":0,"explanation":"धारा वाले तार के चारों ओर चुंबकीय क्षेत्र बनता है।"},{"q":"विद्युत चुंबक में किस पदार्थ का कोर लगता है?","options":["नरम लोहा","लकड़ी","प्लास्टिक","तांबा"],"answer":0,"explanation":"नरम लोहा आसानी से चुंबकीय बनता है और जल्दी खो भी देता है।"}]}$j$),
