  -- 882 Modern Physics & Radioactivity
  (882,'govt_technical','mod-concept','concept',1,'आधुनिक भौतिकी — SSC JE / RRB JE',$j${"note":"JE में अर्ध-आयु का सूत्र और α, β, γ का अंतर अक्सर पूछा जाता है।","text":"रेडियोधर्मिता में अस्थिर नाभिक से α (हीलियम नाभिक), β (इलेक्ट्रॉन/पॉज़िट्रॉन) और γ (विद्युत-चुंबकीय तरंगें, आवेश-रहित) विकिरण निकलते हैं। रेडियोधर्मिता का SI मात्रक बेक्यूरल (Bq) है।"}$j$),
  (882,'govt_technical','mod-formula','formula',2,'अर्ध-आयु का सूत्र',$j${"formula":"N = N₀ × (1/2)^(t/T)","explanation":"N₀ = आरंभिक नाभिक संख्या, N = t समय बाद बचे नाभिक, T = अर्ध-आयु"}$j$),
  (882,'govt_technical','mod-example','example',3,'Numerical (JE style)',$j${"question":"किसी पदार्थ की अर्ध-आयु 10 दिन है। 80 g में से 30 दिन बाद कितना बचेगा?","solution":"3 अर्ध-आयु ⇒ 80 × (1/2)³ = 80/8 = 10 g","answer":"10 g"}$j$),
  (882,'govt_technical','mod-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"कौन सा विकिरण आवेश-रहित और विद्युत-चुंबकीय तरंग है?","options":["γ (गामा)","α (अल्फा)","β (बीटा)","न्यूट्रॉन कण"],"answer":0,"explanation":"γ विकिरण उच्च आवृत्ति की विद्युत-चुंबकीय तरंग है और उस पर आवेश नहीं होता।"},{"q":"ऊर्जा और द्रव्यमान का संबंध किसने दिया?","options":["आइंस्टीन (E = mc²)","न्यूटन","बोर","रदरफोर्ड"],"answer":0,"explanation":"E = mc² आइंस्टीन का सूत्र है।"}]}$j$),
  (882,'govt_basic','mod-concept','concept',1,'रेडियोधर्मिता',$j${"note":"परीक्षा में रेडियोधर्मिता की खोज और अर्ध-आयु की परिभाषा पूछी जाती है।","text":"कुछ तत्वों के नाभिक अपने-आप विकिरण छोड़ते हैं, इसे रेडियोधर्मिता कहते हैं। अर्ध-आयु वह समय है जिसमें नाभिकों की आधी संख्या विघटित हो जाती है।"}$j$),
  (882,'govt_basic','mod-formula','formula',2,'ऊर्जा और द्रव्यमान',$j${"formula":"E = m × c²","explanation":"E = ऊर्जा (J), m = द्रव्यमान (kg), c = प्रकाश की चाल (3×10⁸ m/s)"}$j$),
  (882,'govt_basic','mod-example','example',3,'उदाहरण',$j${"question":"अर्ध-आयु 5 वर्ष है। 40 g पदार्थ 10 वर्ष बाद कितना बचेगा?","solution":"2 अर्ध-आयु ⇒ 40 × (1/2)² = 10 g","answer":"10 g"}$j$),
  (882,'govt_basic','mod-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"रेडियोधर्मिता का SI मात्रक क्या है?","options":["बेक्यूरल (Bq)","न्यूटन","जूल","वाट"],"answer":0,"explanation":"रेडियोधर्मिता का SI मात्रक बेक्यूरल (Bq) है।"},{"q":"अर्ध-आयु क्या दर्शाती है?","options":["आधे नाभिक विघटित होने का समय","पूरा नाभिक विघटित होने का समय","नाभिक का भार","नाभिक का आकार"],"answer":0,"explanation":"अर्ध-आयु वह समय है जिसमें आधे नाभिक विघटित हो जाते हैं।"}]}$j$),
  (882,null,'mod-diagram','svg',5,'नाभिक से विकिरण',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='150' cy='60' r='20' fill='#f59e0b'/><line x1='170' y1='60' x2='260' y2='60' stroke='#14b8a6' stroke-width='3'/><polygon points='260,60 252,55 252,65' fill='#14b8a6'/><line x1='150' y1='40' x2='150' y2='10' stroke='#60a5fa' stroke-width='3'/><text x='150' y='112' text-anchor='middle' fill='#64748b' font-size='11'>अस्थिर नाभिक से विकिरण</text></svg>","caption":"अस्थिर नाभिक स्वयं ऊर्जा और कण छोड़कर स्थिर होता है"}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, exam_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi',
  case
    when s.level_id = 'govt_technical' then array['rrb-je-cbt1','rrb-je-cbt2','ssc-je-paper1']::text[]
    when s.level_id = 'govt_basic' then array['rrb-ntpc-graduate-cbt-1','rrb-ntpc-graduate-cbt-2','rrb-ntpc-ug-cbt-1','rrb-ntpc-ug-cbt-2']::text[]
    else '{}'::text[]
  end,
  'general-science', 'medium', md5(s.body::text)
from src s
on conflict do nothing;
